$ErrorActionPreference = 'Stop'
$secretPath = Join-Path (Split-Path -Parent $PSScriptRoot) '.local\secrets.json'
if (!(Test-Path -LiteralPath $secretPath)) { & (Join-Path $PSScriptRoot 'Initialize-Local.ps1') }
$settings = Get-Content -LiteralPath $secretPath -Raw | ConvertFrom-Json
function Read-PrivateValue([string]$prompt) { $secureValue=Read-Host $prompt -AsSecureString; return [System.Net.NetworkCredential]::new('', $secureValue).Password }
function Read-AdminPassword {
    while ($true) {
        $value = Read-PrivateValue 'Admin password: 12-128 chars, uppercase/lowercase/digit/symbol'
        if ($value.Length -ge 12 -and $value.Length -le 128 -and $value -cmatch '[A-Z]' -and $value -cmatch '[a-z]' -and $value -match '[0-9]' -and $value -match '[^a-zA-Z0-9]') { return $value }
        Write-Host 'Password is not strong enough. Please enter again; it was not saved.' -ForegroundColor Yellow
    }
}
Write-Host 'Enter secrets here on your computer; do not send them in chat.'
$choice = Read-Host 'Configure Email, SpeedSms, Twilio, Admin, or Hosting'
switch ($choice.ToLowerInvariant()) {
 'email' { $value=@{ Host=(Read-Host 'SMTP host'); Port=[int](Read-Host 'Port 587 STARTTLS or 465 TLS'); Username=(Read-Host 'SMTP username/email'); Password=(Read-PrivateValue 'SMTP app password'); From=(Read-Host 'Verified sender email') }; if ($value.Host -eq 'smtp.gmail.com') { $value.Password=$value.Password.Replace(' ',''); if ($value.Password.Length -ne 16) { throw 'Gmail requires the 16-character app password generated by Google. Existing settings were not overwritten.' } }; $settings | Add-Member -NotePropertyName Smtp -NotePropertyValue $value -Force }
 'sms' { $value=@{ AccountSid=(Read-Host 'Twilio Account SID'); AuthToken=(Read-PrivateValue 'Twilio Auth Token'); From=(Read-Host 'Approved sender/number') }; $settings | Add-Member -NotePropertyName Twilio -NotePropertyValue $value -Force }
 'twilio' { $value=@{ AccountSid=(Read-Host 'Twilio Account SID'); AuthToken=(Read-PrivateValue 'Twilio Auth Token'); From=(Read-Host 'Approved sender/number') }; $settings | Add-Member -NotePropertyName Twilio -NotePropertyValue $value -Force }
 'speedsms' { $value=@{ AccessToken=(Read-PrivateValue 'SpeedSMS API access token'); SmsType=4; Sender='' }; $settings | Add-Member -NotePropertyName SpeedSms -NotePropertyValue $value -Force }
 'admin' { $value=@{ Email=(Read-Host 'Your real admin email'); Phone=(Read-Host 'Your phone +84'); Password=(Read-AdminPassword) }; $settings | Add-Member -NotePropertyName Bootstrap -NotePropertyValue $value -Force }
 'hosting' { $value=@{ SqlHost='sql8010.site4now.net'; SqlDatabase='db_ad0641_ducatt'; SqlUser='db_ad0641_ducatt_admin'; SqlPassword=(Read-PrivateValue 'Database password you set when creating DucAtt'); FtpHost='WIN8178.SITE4NOW.NET'; FtpUsername='hoangcongduc-001'; FtpPassword=(Read-PrivateValue 'Hosting plan FTP/WebDeploy password'); SiteFolder='site1'; ApiBaseUrl='https://hoangcongduc-001-site1.itempurl.com' }; $settings | Add-Member -NotePropertyName Hosting -NotePropertyValue $value -Force }
 default { throw 'Choose Email, SpeedSms, Twilio, Admin, or Hosting.' }
}
$settings | ConvertTo-Json -Depth 8 | Set-Content -LiteralPath $secretPath -Encoding UTF8
Write-Output 'Saved in git-ignored local settings. Restart the API to reload.'
